(279, 1, 'CONSTELLATION', 'LONE STAR SS79', 'Aeroporto de Cabo Frio', '{"grupo":"CONSTELLATION","unidade":"LONE STAR SS79","data":"2026-06-03","local":"Aeroporto de Cabo Frio","modal":"Helicóptero","preposto":"Ítalo Gabriel","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"06","m1":"30","label2":"Real","h2":"06","m2":"45"}],"embarque_previsto":"09:30","embarque_real":"09:13","atendimento_inicio":"06:46","atendimento_fim":"11:39"},"info_troca":"Originalmente o tripulante BRUNO PISSOLATO FERREIRA constava no voo, mas foi retirado e BRUNO ANDRADE DE AZEVEDO irá embarcar em seu lugar.","pax_embarcando":"*CONSTELLATION*\n1.ALBERTO VINHAS DE BEM  \n2.CESAR SOARES MASSI  \n3.JADIRLAN SCHUBERT DOS SANTOS  \n4.JAMILSON ELEUTERIO DELESPOSTE  \n5.LAURO MONTEIRO FERNANDES  \n6.LEONARDO SETIMI DOS SANTOS  \n7.LUANA APARECIDA FERREIRA LACERDA  \n8.LUCAS DE AZEVEDO MACIEL  \n9.MARION BARRETO SANTOS  \n10.RUAAN MACEDO DE AQUINO MARTINS  \n11.WILDEN FERNANDES DE LIMA  \n\n*EXPRO*\n12.BRUNO ANDRADE DE AZEVEDO\n13.CELIO COUTO NEVES PRUST \n\n*BRAVA ENERGIA*\n14.CLOVIS ALVES DE ALMEIDA JUNIOR\n15.EUCLIDES TREVISOL JÚNIOR  \n\n*BAKER HUGHES*\n16.DIEGO FIRMINO CORA  \n\n*SLB*\n17.EMANUELLA LAYNE FERREIRA VIDAL BEZERRIL  \n\n*SUBSEA 7*\n18.FREDERICO NUNES GUEDES  \n\n*ENVIRONPACT*\n19.IVAN HIKARI KAWATA","pax_desembarcando":"*CONSTELLATION*\n1.DIEGO MOLIARTE PAULA DOS SANTOS\n2.DOUGLAS DOS SANTOS VIEIRA\n3.FABIO DE PAULA BERGE\n4.GABRIEL BORGES DE MOURA\n5.HUGO ITALO MARTINS ARAUJO\n6.JEFFERSON RODRIGUES\n7.JORGE LUIZ LAMOGLIA\n8.JUSLEY SIQUEIRA ROCHA\n9.LEONARDO SILVA DOS REIS\n10.LUIZ GUSTAVO MARCELINO\n11.RODRIGO FRANCA DO AMARAL COSTA\n12.THIAGO LYNKER DA SILVA BERNADES\n\n*BRAVA ENERGIA*\n13.ALVARO GUILHERME ALTENKIRCH BORBA JUNIO\n14.FRANCISCO ROSEMBERG DE GOIS ALENCAR\n15.PAULO ROBERTO CARDOSO\n\n*BAKER HUGHES \/ BRAVA ENERGIA*\n16.IEGO ANDREY ALVES SOARES\n\n*SLB*\n17.EMANUEL FAUSTO CHAGAS\n\n*SUBSEA 7*\n18.ALCIDES COSTA JUNIOR\n\n*UNIFLEX*\n19.LINDOMAR FRANCA DA CRUZ","fotos":[]}', 0, NULL, '2026-06-04 18:50:04', '2026-07-10 10:05:16', 'TECHNIP', NULL, NULL, '187.63.9.234'),
(280, 4, 'TECHNIP', 'SKANDI VITORIA TFMC TRANSFERIDO', 'AEROMAC', '{"grupo":"TECHNIP","unidade":"SKANDI VITORIA TFMC TRANSFERIDO","data":"2026-06-04","local":"AEROMAC","modal":"Helicóptero","preposto":"Rayssa Pacheco Ferreira Gabriel","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"10","m1":"50","label2":"Real","h2":"10","m2":"54"}],"embarque_previsto":"12:50","embarque_real":"13:13","atendimento_inicio":"10:17","atendimento_fim":"15:56"},"info_troca":"Aeronave não pousou por más condições na unidade&nbsp;","pax_embarcando":"      *TFMC*\n\n1. MAURO DIONES MENEGARDO DA CONCEICAO\n2. FLAVIO BAIAO GUIMARAES\n3. STEPHANIE QUEIROZ FELIX DA SILVA\n4. VICTOR CORDEIRO DOS SANTOS\n5. NATAN TINOCO CURSINO\n6. ANDRE PRIMO DOS SANTOS RODRIGUES\n\n           *TERCEIRIZADO*\n\n7. ⁠RAFAEL FERREIRA DE FREITAS","pax_desembarcando":"NÃO HOUVE DESEMBARQUE ","fotos":[]}', 0, NULL, '2026-06-04 19:01:24', '2026-07-10 10:05:16', 'TECHNIP', NULL, NULL, '189.53.200.138');
